use vstd::prelude::*;

verus! {

/// A sequence is "happy" iff:
/// 1) length >= 3, and
/// 2) for every i in [0, len-3], the triple s[i], s[i+1], s[i+2] are pairwise distinct.
pub open spec fn happy_seq(s: Seq<char>) -> bool {
    s.len() >= 3
    && forall|i: int|
        0 <= i && i <= s.len() - 3 ==>
            s[i] != s[i + 1]
            && s[i] != s[i + 2]
            && s[i + 1] != s[i + 2]
}

fn is_happy(s: Vec<char>) -> (result: bool)
    ensures
        // Functional correctness: result exactly matches the spec definition.
        result == happy_seq(s@)
{
    let n = s.len();
    if n < 3 {
        return false;
    }

    let mut i: usize = 0;
    while i + 2 < n
        invariant
            n == s.len(),
            n >= 3,
            i <= n - 2,
            // All previously checked triples satisfy the pairwise-distinct property
            forall|j: int|
                0 <= j && j < i as int ==>
                    s@[j] != s@[j + 1]
                    && s@[j] != s@[j + 2]
                    && s@[j + 1] != s@[j + 2]
    {
        let a = s[i];
        let b = s[i + 1];
        let c = s[i + 2];

        if a == b || a == c || b == c {
            return false;
        }

        i = i + 1;
    }

    true
}

} // verus!